public struct FfiConverterTypeRusshError: FfiConverterRustBuffer {
    typealias SwiftType = RusshError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RusshError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ConnectionFailed(
            kind: try FfiConverterTypeConnectionFailureKind.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Closed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .AuthenticationFailed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Key(
            kind: try FfiConverterTypeKeyErrorKind.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Sftp(
            code: try FfiConverterUInt32.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ChannelOpenFailed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidState(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RusshError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .ConnectionFailed(kind,message):
            writeInt(&buf, Int32(1))
            FfiConverterTypeConnectionFailureKind.write(kind, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Closed(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .AuthenticationFailed(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Key(kind,message):
            writeInt(&buf, Int32(4))
            FfiConverterTypeKeyErrorKind.write(kind, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Sftp(code,message):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ChannelOpenFailed(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidState(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


